import {lessons,position,pawnFacts,theorySources} from './lessons.js';
import {guides,ratingPolicy} from './catalog.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function miniBoard(c,label){return `<div class="structure-board" role="img" aria-label="${esc(label)} 폰 구조">${[8,7,6,5,4,3,2,1].flatMap(r=>[...'abcdefgh'].map((f,i)=>{const p=c.get(f+r);return `<div class="mini-square ${(i+r)%2===1?'mini-dark':''}">${p?.type==='p'?`<img src="./pieces/${p.color}P.svg" alt="${p.color==='w'?'백':'흑'} 폰 ${f+r}">`:''}</div>`})).join('')}</div>`;}
export function mountLearning(g,load){const l=lessons[g.id],cases=l.cases.filter(s=>!s.label.includes('위나워')).slice(0,3);let index=0;const root=document.getElementById('learning');root.innerHTML=`<div class="section-heading"><h2>이 구조에서 기억할 것</h2><a href="#strategy-compare">다른 오프닝과 비교 ↗</a></div><label for="study-case" class="small muted">대표 구조 선택</label><select id="study-case" class="line-select">${cases.map((s,i)=>`<option value="${i}">${esc(s.label)}</option>`).join('')}</select><div id="case-content"></div>`;function draw(){const s=cases[index],c=position(s.line),facts=pawnFacts(c);document.getElementById('case-content').innerHTML=`<p class="case-purpose">${esc(s.purpose)}</p><div class="plans">${s.plans.map((arr,i)=>`<div class="plan"><h3>${i?'♚ 흑':'♔ 백'}의 다음 계획</h3><ol class="essential-plan">${[arr[1],arr[2],arr[3]].map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="small muted">목표: ${esc(arr[6])}</p></div>`).join('')}</div><div class="essential-counter"><b>상대가 바꾸려는 것</b><ul>${s.counters.slice(0,2).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="compact-detail"><summary>폰 구조와 말의 역할 확인</summary><div class="structure-layout"><div>${miniBoard(c,s.label)}<button id="study-load" class="primary wide">이 국면에서 다른 수 계산</button></div><div><p>${esc(s.structure)}</p>${s.pieces.map((x,i)=>`<p><b>${i?'흑':'백'}</b> · ${esc(x)}</p>`).join('')}<p class="small muted">열린 파일: ${facts.open.join('·')||'없음'} · 더블폰: 백 ${facts.white.doubled.join('·')||'없음'} / 흑 ${facts.black.doubled.join('·')||'없음'}</p></div></div></details>`;document.getElementById('study-load').onclick=()=>load(s.line,s.label,s);}document.getElementById('study-case').onchange=e=>{index=+e.target.value;draw()};draw();}
let left='french',right='caro';
export function strategyCompare(){function draw(){const choices=[left,right].map(id=>guides.find(g=>g.id===id)||guides[0]),cases=choices.map(g=>lessons[g.id].cases[0]);document.getElementById('main').innerHTML=`<div class="eyebrow">COMPARE PLANS</div><h1>전략 비교</h1><p class="subtitle">중앙을 다루는 방법과 다음 계획만 나란히 봅니다.</p><div class="compare-presets">${[['open-game','sicilian','e5 vs 시실리안'],['french','caro','프렌치 vs 카로칸'],['italian','ruy','이탈리안 vs 루이 로페즈'],['sicilian-dragon','sicilian-accelerated','드래곤 vs 액셀러레이티드']].map(([a,b,t])=>`<button data-left="${a}" data-right="${b}">${t}</button>`).join('')}</div><div class="compare-pickers">${choices.map((g,i)=>`<label>${i?'두 번째':'첫 번째'} 오프닝<select id="compare-${i}" class="line-select">${guides.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="table-wrap strategy-table"><table><thead><tr><th>기준</th>${choices.map(g=>`<th><a href="#opening/${g.id}">${esc(g.name)}</a></th>`).join('')}</tr></thead><tbody>${[['왜 선택하나',s=>s.purpose],['백의 계획',s=>[s.plans[0][1],s.plans[0][2],s.plans[0][3]].join(' → ')],['흑의 계획',s=>[s.plans[1][1],s.plans[1][2],s.plans[1][3]].join(' → ')],['상대의 반격',s=>s.counters[0]]].map(([t,fn])=>`<tr><th>${t}</th>${cases.map(s=>`<td>${esc(fn(s))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{left=b.dataset.left;right=b.dataset.right;draw()});[0,1].forEach(i=>document.getElementById('compare-'+i).onchange=e=>{if(i)right=e.target.value;else left=e.target.value;draw()});}draw();}
export function sourceNotes(sources){return `<h1>출처와 선정 기준</h1><div class="callout"><strong>학습 목록 선정 기준</strong>${ratingPolicy}<br>‘Really, Bro’·‘Tricks Only’·‘Garbage’는 제외 구간입니다. 두 척도를 합산하거나 객관적 강함으로 환산하지 않습니다.</div>${sources.filter((_,i)=>i!==4).map(s=>`<div class="source-card"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><p>${esc(s.url.includes("lichess-org")?"오프닝 분류와 수순 참고에 사용한 CC0 자료입니다. 화면에는 선정한 핵심 가이드만 제공합니다.":s.note)}</p></div>`).join('')}<details class="compact-detail"><summary>전략 해설 참고 자료</summary><div class="source-inline">${theorySources.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`).join('')}</div></details><p class="small muted">수순은 chess.js로 합법성을 확인합니다. 후보 수는 브라우저 내 Stockfish 19 lite의 시간 제한 탐색입니다. 전략 설명과 엔진 계산은 구분합니다. 기물 이미지와 라이브러리의 라이선스는 보존했습니다.</p>`;}
